public interface MarmotInterface {
    
    suspend fun `acceptGroupInvite`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): AppGroupRecordFfi
    
    /**
     * Return the complete locally cached kind-3 follow list for `account_ref`
     * as canonical lowercase public-key hex strings.
     *
     * This is a synchronous, network-free read intended for profile screens
     * and bulk membership checks. Follow/unfollow and directory refreshes
     * update the cache before returning.
     */
    fun `accountFollows`(`accountRef`: kotlin.String): List<kotlin.String>
    
    /**
     * Normalize a public-key reference (hex, `npub`, `nostr:npub`,
     * `nprofile`, `nostr:nprofile`, or a `marmot://profile/` link) to
     * canonical hex. `None` if it isn't a valid public identity
     * reference. nprofile relay hints are discarded. Duplicate type-0
     * TLV entries keep the first key. After wrapper normalization, the
     * nprofile fallback rejects encoded tokens longer than 1023 UTF-8
     * bytes; a valid 1023-byte token still decodes when wrapped. Used
     * to resolve a scanned or deep-linked mention back to the account
     * id the rest of the API expects.
     */
    fun `accountIdHex`(`reference`: kotlin.String): kotlin.String?
    
    fun `accountInboxRelays`(`accountRef`: kotlin.String): List<kotlin.String>
    
    /**
     * Observed relay history for `account_ref`: current and superseded
     * kind-30443 events from one validated fetch window. Clients can pass a
     * superseded event id and its source relays to the existing deletion API.
     */
    suspend fun `accountKeyPackageRelayEvents`(`accountRef`: kotlin.String, `bootstrapRelays`: List<kotlin.String>): List<AccountKeyPackageRelayEventFfi>
    
    /**
     * List the local and relay-discovered Marmot KeyPackage publications for
     * `account_ref`. Relay-backed rows are the current winner per addressable
     * slot in the validated fetch window.
     */
    suspend fun `accountKeyPackages`(`accountRef`: kotlin.String, `bootstrapRelays`: List<kotlin.String>): List<AccountKeyPackageFfi>
    
    fun `accountNip65Relays`(`accountRef`: kotlin.String): List<kotlin.String>
    
    /**
     * Per-account relay lists: the NIP-65 and inbox lists the account has
     * published, plus the configured default/bootstrap sets.
     */
    fun `accountRelayLists`(`accountRef`: kotlin.String): AccountRelayListsFfi
    
    /**
     * Read setup readiness without performing network I/O.
     */
    fun `accountSetupReadiness`(`accountRef`: kotlin.String): AccountSetupReadinessFfi
    
    /**
     * Per-account unread aggregate for the account-switcher and application
     * badge (mdk#461, mdk#1460). Each entry is read from that account's
     * materialized chat-list projection, so this does not require switching
     * into, or loading a full session/timeline for, any account — non-active
     * (not-`running`) local-signing accounts are reported too. This legacy
     * getter omits accounts whose projection read fails.
     * `attention_only_conversations` counts each active pending invitation once
     * and accepted manual-only reminders, without overlapping message totals.
     * Archived chats and departed or departing groups contribute nothing.
     */
    fun `accountUnreadSummary`(): List<AccountUnreadFfi>
    
    suspend fun `acknowledgeDisbandFailure`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): kotlin.Boolean
    
    /**
     * Record Continue anyway for the displayed notice, then resume setup.
     */
    suspend fun `acknowledgeOnboardingSingleDevice`(`accountRef`: kotlin.String, `revision`: kotlin.ULong): OnboardingSnapshotFfi
    
    /**
     * Acknowledge with the epoch and revision from the displayed device notice.
     */
    suspend fun `acknowledgeOnboardingSingleDeviceInEpoch`(`accountRef`: kotlin.String, `revision`: kotlin.ULong, `recoveryEpoch`: kotlin.String): OnboardingSnapshotFfi
    
    /**
     * Read the process-wide app-performance snapshot for debug/diagnostics
     * surfaces and on-demand support dumps.
     *
     * Read-only and privacy-safe by construction: cumulative counters and
     * fixed-bucket millisecond histograms per reviewed operation, with no
     * account, group, message, relay, URL, pubkey, payload, or key material.
     */
    fun `appPerformanceSnapshot`(): AppPerformanceSnapshotFfi
    
    suspend fun `approveOnboardingRepair`(`accountRef`: kotlin.String, `revision`: kotlin.ULong): OnboardingSnapshotFfi
    
    /**
     * Approve with the epoch and revision from the same displayed snapshot.
     */
    suspend fun `approveOnboardingRepairInEpoch`(`accountRef`: kotlin.String, `revision`: kotlin.ULong, `recoveryEpoch`: kotlin.String): OnboardingSnapshotFfi
    
    suspend fun `attachmentDownloadPolicy`(`accountRef`: kotlin.String): AttachmentDownloadPolicyFfi
    
    /**
     * Read 1..=100 attachment slots in canonical newest-first order. Rejected slots
