    var `name`: kotlin.String, 
    var `description`: kotlin.String, 
    var `admins`: List<kotlin.String>, 
    var `relays`: List<kotlin.String>, 
    var `nostrGroupIdHex`: kotlin.String, 
    /**
     * URL-based group avatar (`marmot.group.avatar-url.v1`), `None` when absent.
     * Used when no valid encrypted Blossom image is available. See the shared
     * [presentation contract](https://github.com/marmot-protocol/mdk/blob/master/docs/marmot-architecture/further-context/conversation-presentation.md#sources-and-ownership).
     */
    var `avatarUrl`: kotlin.String?, 
    var `avatarDim`: kotlin.String?, 
    var `avatarThumbhash`: kotlin.String?, 
    /**
     * Content hash of the encrypted Blossom avatar
     * (`marmot.group.blossom.image.v1`), `None` when absent. Doubles as a
     * cache key; fetch + decrypt via `Marmot::download_group_blossom_image`.
     */
    var `imageHashHex`: kotlin.String?, 
    var `encryptedMedia`: AppGroupEncryptedMediaComponentFfi, 
    /**
     * Per-group disappearing-message retention in seconds
     * (`marmot.group.message-retention.v1`). `0` means messages never expire.
     */
    var `disappearingMessageSecs`: kotlin.ULong, 
    var `archived`: kotlin.Boolean, 
    var `pendingConfirmation`: kotlin.Boolean, 
    /**
     * Whether this local group copy is frozen pending verified repair.
     */
    var `unrecoverable`: kotlin.Boolean, 
    /**
     * Whether the local account is still a member of this group, and if not,
     * whether it left voluntarily or was removed.
     */
