    var `accountWorkerReadiness`: AppPerformanceOperationSnapshotFfi, 
    var `accountSessionOpen`: AppPerformanceOperationSnapshotFfi, 
    var `accountGroupHydration`: AppPerformanceOperationSnapshotFfi, 
    var `accountProfileLoad`: AppPerformanceOperationSnapshotFfi, 
    var `accountGroupReadSnapshot`: AppPerformanceOperationSnapshotFfi, 
    var `accountTransportActivation`: AppPerformanceOperationSnapshotFfi, 
    var `accountSubscriptionRegistration`: AppPerformanceOperationSnapshotFfi, 
    var `accountCatchUp`: AppPerformanceOperationSnapshotFfi, 
    var `accountSync`: AppPerformanceOperationSnapshotFfi, 
    var `accountSetupAdvisoryStep`: AppPerformanceOperationSnapshotFfi, 
    var `accountBootstrapRelayAndFollowPublish`: AppPerformanceOperationSnapshotFfi, 
    var `accountDefaultProfilePublish`: AppPerformanceOperationSnapshotFfi, 
    var `accountInitialKeyPackagePublish`: AppPerformanceOperationSnapshotFfi, 
    /**
     * Overlap between initial KeyPackage publication and initial sync. A
     * successful zero-duration sample means publication completed before
     * sync began; it is not a missing duration sample.
     */
    var `accountInitialSyncOverlap`: AppPerformanceOperationSnapshotFfi, 
    var `accountSetupIdentityLocal`: AppPerformanceOperationSnapshotFfi, 
    var `accountSetupStorageLocal`: AppPerformanceOperationSnapshotFfi, 
