public object FfiConverterTypeLocalSendStatusFfi : FfiConverterRustBuffer<LocalSendStatusFfi>{
    override fun read(buf: ByteBuffer): LocalSendStatusFfi {
        return when(buf.getInt()) {
            1 -> LocalSendStatusFfi.Queued
            2 -> LocalSendStatusFfi.EngineOwned
            3 -> LocalSendStatusFfi.Completed(
                FfiConverterTypeSendSummaryFfi.read(buf),
                )
            4 -> LocalSendStatusFfi.Rejected
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
