/**
 * Top-level event firehose, FFI-shaped. Agent streams collapse to a single
 * "agent stream activity" variant — host apps do not differentiate them at
 * the surface level for v1.
 */
sealed class MarmotEventFfi {
    
    data class GroupJoined(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `groupIdHex`: kotlin.String) : MarmotEventFfi() {
        companion object
    }
    
    data class GroupStateUpdated(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `groupIdHex`: kotlin.String) : MarmotEventFfi() {
        companion object
    }
    
    data class MessageReceived(
        val `received`: RuntimeMessageReceivedFfi) : MarmotEventFfi() {
        companion object
    }
    
    data class ProjectionUpdated(
        val `update`: RuntimeProjectionUpdateFfi) : MarmotEventFfi() {
        companion object
    }
    
    data class GroupEvent(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `groupIdHex`: kotlin.String, 
        val `event`: GroupEventKindFfi) : MarmotEventFfi() {
        companion object
    }
    
    data class AccountError(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `message`: kotlin.String) : MarmotEventFfi() {
        companion object
    }
    
    data class AgentStreamActivity(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String) : MarmotEventFfi() {
        companion object
    }
    
    /**
     * A confirmed create/invite could not deliver a welcome to `recipient_hex`;
     * that member is in the group but unjoinable until the welcome is
     * re-delivered via `redeliver_welcome(message_id_hex)` (mdk#352).
     */
    data class WelcomeDeliveryPending(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `groupIdHex`: kotlin.String, 
        val `messageIdHex`: kotlin.String, 
        val `recipientHex`: kotlin.String) : MarmotEventFfi() {
        companion object
    }
    
    /**
     * This device armed `arms` epoch-gap history backfills for the group with
     * no sign in between that it caught up: it is still at `stalled_epoch`.
     * Surface it as "this group cannot catch up; re-syncing is recommended";
     * the sanctioned repair is rotating this device's key package and
     * re-activating transport, which is the host app's call.
     */
    data class EpochStallEscalated(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `groupIdHex`: kotlin.String, 
        val `stalledEpoch`: kotlin.ULong, 
        val `arms`: kotlin.UInt) : MarmotEventFfi() {
        companion object
    }
    
    /**
     * A group change this device committed lost a same-epoch race and was
     * withdrawn by branch selection. `kind` names the change
     * (`group_profile`, `app_components`, `remove_members`, `invite`),
     * `outcome` says what the runtime did about it (`reissued`, `conflict`,
     * `already_satisfied`, `reinvite_required`, `abandoned`, `not_member`),
     * and `reason` is a stable low-cardinality explanation. Only `reissued`
     * needs no user action; every other outcome means the change did not
     * land and the host should tell the user (mdk#1734).
     */
    data class GroupChangeSuperseded(
        val `accountIdHex`: kotlin.String, 
        val `accountLabel`: kotlin.String, 
        val `groupIdHex`: kotlin.String, 
        val `commitIdHex`: kotlin.String, 
        val `kind`: kotlin.String, 
        val `outcome`: kotlin.String, 
        val `reason`: kotlin.String) : MarmotEventFfi() {
        companion object
    }
    

    
    companion object
}

