                FfiConverterTypeRuntimeProjectionUpdateFfi.write(value.`update`, buf)
                Unit
            }
            is MarmotEventFfi.GroupEvent -> {
                buf.putInt(5)
                FfiConverterString.write(value.`accountIdHex`, buf)
                FfiConverterString.write(value.`accountLabel`, buf)
                FfiConverterString.write(value.`groupIdHex`, buf)
                FfiConverterTypeGroupEventKindFfi.write(value.`event`, buf)
                Unit
            }
            is MarmotEventFfi.AccountError -> {
                buf.putInt(6)
                FfiConverterString.write(value.`accountIdHex`, buf)
                FfiConverterString.write(value.`accountLabel`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is MarmotEventFfi.AgentStreamActivity -> {
                buf.putInt(7)
                FfiConverterString.write(value.`accountIdHex`, buf)
                FfiConverterString.write(value.`accountLabel`, buf)
                Unit
            }
            is MarmotEventFfi.WelcomeDeliveryPending -> {
                buf.putInt(8)
                FfiConverterString.write(value.`accountIdHex`, buf)
                FfiConverterString.write(value.`accountLabel`, buf)
                FfiConverterString.write(value.`groupIdHex`, buf)
                FfiConverterString.write(value.`messageIdHex`, buf)
                FfiConverterString.write(value.`recipientHex`, buf)
                Unit
            }
            is MarmotEventFfi.EpochStallEscalated -> {
                buf.putInt(9)
                FfiConverterString.write(value.`accountIdHex`, buf)
                FfiConverterString.write(value.`accountLabel`, buf)
                FfiConverterString.write(value.`groupIdHex`, buf)
                FfiConverterULong.write(value.`stalledEpoch`, buf)
                FfiConverterUInt.write(value.`arms`, buf)
                Unit
            }
            is MarmotEventFfi.GroupChangeSuperseded -> {
                buf.putInt(10)
                FfiConverterString.write(value.`accountIdHex`, buf)
                FfiConverterString.write(value.`accountLabel`, buf)
                FfiConverterString.write(value.`groupIdHex`, buf)
                FfiConverterString.write(value.`commitIdHex`, buf)
                FfiConverterString.write(value.`kind`, buf)
                FfiConverterString.write(value.`outcome`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







