/**
 * One `imeta` attachment of a message, in tag order. `attachment_index` is the
 * position among the message's `imeta` tags (rejected siblings included), so a
 * host can render media and placeholders in order and correlate a timeline
 * row with `list_media` records for the same message. Pass an `Accepted`
 * reference to `download_media`; render `Rejected` as an unsupported/invalid
 * attachment placeholder using `rejection.kind`.
 */
sealed class MediaAttachmentOutcomeFfi {
    
    data class Accepted(
        val `attachmentIndex`: kotlin.UInt, 
        val `reference`: MediaAttachmentReferenceFfi) : MediaAttachmentOutcomeFfi() {
        companion object
    }
    
    data class Rejected(
        val `attachmentIndex`: kotlin.UInt, 
        val `rejection`: MediaAttachmentRejectionFfi) : MediaAttachmentOutcomeFfi() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMediaAttachmentOutcomeFfi : FfiConverterRustBuffer<MediaAttachmentOutcomeFfi>{
    override fun read(buf: ByteBuffer): MediaAttachmentOutcomeFfi {
        return when(buf.getInt()) {
            1 -> MediaAttachmentOutcomeFfi.Accepted(
                FfiConverterUInt.read(buf),
                FfiConverterTypeMediaAttachmentReferenceFfi.read(buf),
                )
            2 -> MediaAttachmentOutcomeFfi.Rejected(
                FfiConverterUInt.read(buf),
                FfiConverterTypeMediaAttachmentRejectionFfi.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MediaAttachmentOutcomeFfi) = when(value) {
        is MediaAttachmentOutcomeFfi.Accepted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`attachmentIndex`)
                + FfiConverterTypeMediaAttachmentReferenceFfi.allocationSize(value.`reference`)
            )
        }
        is MediaAttachmentOutcomeFfi.Rejected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`attachmentIndex`)
                + FfiConverterTypeMediaAttachmentRejectionFfi.allocationSize(value.`rejection`)
            )
        }
    }

    override fun write(value: MediaAttachmentOutcomeFfi, buf: ByteBuffer) {
        when(value) {
            is MediaAttachmentOutcomeFfi.Accepted -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`attachmentIndex`, buf)
                FfiConverterTypeMediaAttachmentReferenceFfi.write(value.`reference`, buf)
                Unit
            }
            is MediaAttachmentOutcomeFfi.Rejected -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`attachmentIndex`, buf)
                FfiConverterTypeMediaAttachmentRejectionFfi.write(value.`rejection`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Stable category of an encrypted-media attachment rejection (mdk#1787).
 * Branch on this instead of parsing `detail`; the set only grows.
 */

enum class MediaAttachmentRejectionKindFfi {
    
    /**
     * Not a decodable encrypted-media `imeta` tag (wrong marker, a non-string
     * element, a field without its value, a locator without `kind value`).
     */
    INVALID_STRUCTURE,
    /**
     * The `v` field is absent or names a format this build does not
     * implement. Legacy MIP-era and future shapes land here: render as
     * "unsupported attachment", not as corrupt content.
     */
    UNSUPPORTED_FORMAT,
    /**
     * A required field is absent or empty.
     */
    MISSING_FIELD,
    /**
     * A single-occurrence field appears more than once.
     */
    DUPLICATE_FIELD,
    /**
     * A present field has an invalid value (hash, nonce, locator URL, media
     * type, filename, or a forbidden `blurhash`).
