            is SearchUpdateTriggerFfi.ResultsFound -> {
                buf.putInt(2)
                FfiConverterUByte.write(value.`radius`, buf)
                Unit
            }
            is SearchUpdateTriggerFfi.DiscoveryResultsFound -> {
